<?php
require_once __DIR__.'/_header.php';$page_title='Story Gallery';$storyId=(int)($_GET['story_id']??0);$story=db()->prepare('SELECT id,title FROM stories WHERE id=?');$story->execute([$storyId]);$story=$story->fetch();if(!$story)exit('Story not found');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!empty($_FILES['images']['name'][0])){foreach($_FILES['images']['tmp_name'] as $i=>$tmp){if(!is_uploaded_file($tmp)||$_FILES['images']['error'][$i]!==UPLOAD_ERR_OK)continue;$mime=(new finfo(FILEINFO_MIME_TYPE))->file($tmp);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];if(!isset($allowed[$mime])||$_FILES['images']['size'][$i]>5242880)continue;$name=bin2hex(random_bytes(12)).'.'.$allowed[$mime];$dir=__DIR__.'/../uploads/stories';if(!is_dir($dir))mkdir($dir,0755,true);if(move_uploaded_file($tmp,$dir.'/'.$name))db()->prepare('INSERT INTO story_images(story_id,image_path,caption,credit) VALUES(?,?,?,?)')->execute([$storyId,'uploads/stories/'.$name,trim($_POST['caption']??''),trim($_POST['credit']??'')]);}log_admin_activity('gallery_upload','story '.$storyId);flash('success','Gallery updated.');}redirect('/admin/gallery.php?story_id='.$storyId);}
$images=db()->prepare('SELECT * FROM story_images WHERE story_id=? ORDER BY sort_order,id');$images->execute([$storyId]);$images=$images->fetchAll();
?><div class="content"><div class="card"><h2><?=e($story['title'])?> gallery</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="field"><label>Images</label><input type="file" name="images[]" multiple accept="image/jpeg,image/png,image/webp"></div><div class="field"><label>Caption</label><input name="caption"></div><div class="field"><label>Credit</label><input name="credit"></div><button>Upload images</button></form><?php foreach($images as $image):?><p><img src="<?=BASE_URL?>/<?=e($image['image_path'])?>" style="width:100px;vertical-align:middle"> <?=e($image['caption']??'')?> · <?=e($image['credit']??'')?></p><?php endforeach;?></div></div>
